/*
 * A250580  Number of (n+1)X(5+1) 0..1 arrays with nondecreasing
 *          max(x(i,j),x(i,j-1)) in the i direction and nondecreasing
 *          min(x(i,j),x(i-1,j)) in the j direction.
 * https://oeis.org/A250580
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) computed via a linear recurrence of order 12 for n > 14.
 *            The first 14 terms are generated by a small DP based on the
 *            array constraints. After the 14th term the recurrence a(n) =
 *            7*a(n-1) -15*a(n-2) -4*a(n-3) +64*a(n-4) -90*a(n-5) +9*a(n-6)
 *            +94*a(n-7) -96*a(n-8) +31*a(n-9) +6*a(n-10) -6*a(n-1...
 * Range:     u8 none, u16 n <= 7, u32 n <= 20, u64 n <= 47, u128 n <= 99,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

static bool init_done = false;
static seq_t base[15];   /* base[1..14] : first 14 terms */

static bool valid_mask(uint8_t prev, uint8_t curr)
{
    /* Check all j = 1..5 */
    for (int j = 1; j < 6; ++j) {
        int prev_j    = (prev >> j) & 1;
        int prev_j1   = (prev >> (j-1)) & 1;
        int curr_j    = (curr >> j) & 1;
        int curr_j1   = (curr >> (j-1)) & 1;

        /* max condition in i-direction */
        int maxPrev = (prev_j > prev_j1) ? prev_j : prev_j1;
        int maxCurr = (curr_j > curr_j1) ? curr_j : curr_j1;
        if (maxCurr < maxPrev) return false;

        /* min condition in j-direction */
        int minCurr = (curr_j < prev_j) ? curr_j : prev_j;
        int minPrev = (curr_j1 < prev_j1) ? curr_j1 : prev_j1;
        if (minCurr < minPrev) return false;
    }
    return true;
}

static void init_base(void)
{
    seq_t dp_prev[64], dp_curr[64];
    for (int m = 0; m < 64; ++m) dp_prev[m] = 1;   /* row 0 */
    for (int row = 1; row <= 14; ++row) {
        for (int curr = 0; curr < 64; ++curr) {
            seq_t s = 0;
            for (int prev = 0; prev < 64; ++prev) {
                if (valid_mask((uint8_t)prev, (uint8_t)curr))
                    s += dp_prev[prev];
            }
            dp_curr[curr] = s;
        }
        /* copy for next iteration */
        for (int m = 0; m < 64; ++m) dp_prev[m] = dp_curr[m];
        /* sum over all mask values to get a(row) */
        seq_t total = 0;
        for (int m = 0; m < 64; ++m) total += dp_prev[m];
        base[row] = total;
    }
    init_done = true;
}

seq_t a(idx_t n)
{
    if (!init_done) init_base();

    if (n <= 14) return base[(idx_t)n];

    /* Buffer holds a(k-12)...a(k-1) for current k.  Start with
       a(3)...a(14) because a(15) needs a(3)...a(14).      */
    seq_t buf[12];
    for (int i = 0; i < 12; ++i) buf[i] = base[3 + i];

    seq_t new_val = 0;
    for (idx_t k = 15; k <= n; ++k) {
        seq_t pos = 7  * buf[11];
        pos += 64 * buf[8];
        pos += 9  * buf[6];
        pos += 94 * buf[5];
        pos += 31 * buf[3];
        pos += 6  * buf[2];
        pos +=       buf[0];

        seq_t neg = 15 * buf[10];
        neg += 4  * buf[9];
        neg += 90 * buf[7];
        neg += 96 * buf[4];
        neg += 6  * buf[1];

        new_val = pos - neg;

        for (int i = 0; i < 11; ++i) buf[i] = buf[i+1];
        buf[11] = new_val;
    }
    return new_val;
}
